function Write-CaptureGateHeartbeat([string]$Phase){Write-Output ("captureGate phase={0} elapsedMs={1}"-f$Phase,$gateClock.ElapsedMilliseconds)}
function Get-Sha256Hex([string]$Path){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($Path))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}}
function Get-TextSha256([string]$Text){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}}
function Assert-GameplayUltraQualityReceipt($Receipt,[string]$Label){
  if($Receipt.requestedRenderQuality-ne'ULTRA'-or$Receipt.actualRenderQuality-ne'ULTRA'-or$Receipt.developmentUltraRendererApplied-ne1-or$Receipt.developmentUltraTransitionApplied-ne1){throw "$Label quality honesty failed"}
  $components=@('shadowResourcesApplied','volumetricResolutionApplied','cloudSamplesApplied','cloudShadowSamplesApplied','lightShaftSamplesApplied','vegetationDensityApplied','textureBudgetApplied','meshBudgetApplied');$present=@($components|Where-Object{$null-ne$Receipt.PSObject.Properties[$_]})
  if($present.Count-and($present.Count-ne$components.Count-or$Receipt.shadowResourcesApplied-ne1-or$Receipt.volumetricResolutionApplied-ne1-or$Receipt.cloudSamplesApplied-ne0-or$Receipt.cloudShadowSamplesApplied-ne0-or$Receipt.lightShaftSamplesApplied-ne0-or$Receipt.vegetationDensityApplied-ne0-or$Receipt.textureBudgetApplied-ne0-or$Receipt.meshBudgetApplied-ne0)){throw "$Label quality component truth failed"}
  foreach($field in @('pendingGpuReleaseBytes','gpuValidationErrors','gpuValidationWarnings','debugErrorCount','debugWarningCount')){if($null-ne$Receipt.PSObject.Properties[$field]-and[uint64]$Receipt.$field-ne0){throw "$Label GPU truth failed: $field"}}
  foreach($field in @('completedGpuFrameSerial','renderQualityEpoch')){if($null-ne$Receipt.PSObject.Properties[$field]-and[uint64]$Receipt.$field-lt1){throw "$Label GPU serial truth failed: $field"}}
}
function Get-LumaSsim([string]$Left,[string]$Right){
  $a=[Drawing.Bitmap]::FromFile($Left);$b=[Drawing.Bitmap]::FromFile($Right);try{if($a.Width-ne$b.Width-or$a.Height-ne$b.Height){return 0.0};$n=0.0;$sx=0.0;$sy=0.0;$sxx=0.0;$syy=0.0;$sxy=0.0;for($y=2;$y-lt$a.Height;$y+=4){for($x=2;$x-lt$a.Width;$x+=4){$ca=$a.GetPixel($x,$y);$cb=$b.GetPixel($x,$y);$va=.2126*$ca.R+.7152*$ca.G+.0722*$ca.B;$vb=.2126*$cb.R+.7152*$cb.G+.0722*$cb.B;$n++;$sx+=$va;$sy+=$vb;$sxx+=$va*$va;$syy+=$vb*$vb;$sxy+=$va*$vb}};$mx=$sx/$n;$my=$sy/$n;$vx=[Math]::Max(0,$sxx/$n-$mx*$mx);$vy=[Math]::Max(0,$syy/$n-$my*$my);$cov=$sxy/$n-$mx*$my;$c1=[Math]::Pow(.01*255,2);$c2=[Math]::Pow(.03*255,2);$value=((2*$mx*$my+$c1)*(2*$cov+$c2))/(($mx*$mx+$my*$my+$c1)*($vx+$vy+$c2));return [Math]::Max(0,[Math]::Min(1,$value))}finally{$a.Dispose();$b.Dispose()}}
function Get-CaptureStateSha($receipt,$environment,$collision,$palette,$character,$camera,$sequence,$photoreal){
  $parts=@();foreach($typed in @($receipt,$environment,$collision,$palette,$character,$camera,$sequence,$photoreal)){$state=[ordered]@{};foreach($property in $typed.PSObject.Properties){if($property.Name-ne'runId'){$state[$property.Name]=$property.Value}};$parts+=($state|ConvertTo-Json -Depth 20 -Compress)}
  return Get-TextSha256 ($parts-join'|')
}
function Get-GameplayCanonicalEntityMismatch($LeftCharacter,$RightCharacter){for($captureIndex=0;$captureIndex-lt@($LeftCharacter.captures).Count;++$captureIndex){$leftCapture=$LeftCharacter.captures[$captureIndex];$rightCapture=$RightCharacter.captures[$captureIndex];$leftEntities=@($leftCapture.captureStateEntityDiagnostics);$rightEntities=@($rightCapture.captureStateEntityDiagnostics);if($leftEntities.Count-ne$rightEntities.Count){return "capture=$($leftCapture.name) entityCount=$($leftEntities.Count)/$($rightEntities.Count)"};for($entityIndex=0;$entityIndex-lt$leftEntities.Count;++$entityIndex){$left=$leftEntities[$entityIndex];$right=$rightEntities[$entityIndex];foreach($field in @('stableId','source','category','dynamic','alive','topologyHash','transformHash','positionRawBits','rotationRawBits')){if(($left.$field|ConvertTo-Json -Compress)-cne($right.$field|ConvertTo-Json -Compress)){return "capture=$($leftCapture.name) stableId=$($left.stableId) field=$field left=$(($left.$field|ConvertTo-Json -Compress)) right=$(($right.$field|ConvertTo-Json -Compress))"}}}}return 'no typed entity mismatch'}
