function Save-RunEvidence([int]$Run,$receipt,$environment,$collision,$palette,$character,$camera,$sequence,$hdr,$photoreal,$TemporalGhostEvidence){
  $runDirectory=Join-Path $directory "determinism-runs/run-$Run";New-Item -ItemType Directory -Force -Path $runDirectory|Out-Null;$entries=@()
  foreach($name in $names){$stem=[IO.Path]::GetFileNameWithoutExtension($name);$artifacts=@($name,"$stem-object-id.png","$stem-raw.png","$stem-raw-object-id.png","$stem-depth.png","$stem-raw-depth.png","$stem-tokens.bin","$stem-tokens.json","$stem-raw-tokens.bin","$stem-raw-tokens.json");if($name-like'third-*'-or$name-in@('palette-building.png','melee-combat.png')){$artifacts+=@("$stem-reference.png","$stem-reference-object-id.png","$stem-reference-depth.png","$stem-contact.png","$stem-reference-contact.png")};foreach($diagnosticArtifact in @("$stem-atmosphere-rgba16f.bin","$stem-atmosphere-output.json","$stem-atmosphere-scene-rgba16f.bin","$stem-atmosphere-scene.json")){if(Test-Path -LiteralPath (Join-Path $directory $diagnosticArtifact)){$artifacts+=$diagnosticArtifact}};foreach($artifact in $artifacts){$source=Join-Path $directory $artifact;if(-not(Test-Path -LiteralPath $source)){throw "Missing run $Run artifact: $artifact"};$destination=Join-Path $runDirectory $artifact;Copy-Item -LiteralPath $source -Destination $destination -Force;$entries+=@{name=$artifact;sha256=Get-Sha256Hex $destination}}}
  foreach($receiptName in $runReceiptNames){Copy-Item -LiteralPath (Join-Path $directory $receiptName) -Destination (Join-Path $runDirectory $receiptName) -Force}
  $hdrEntries=@(Assert-GameplayHdrCaptureEvidence $directory $hdr $sequence $names $validatorPath $receipt.runId);foreach($entry in $hdrEntries){$destination=Join-Path $runDirectory $entry.path;Copy-Item -LiteralPath (Join-Path $directory $entry.path) -Destination $destination -Force;$null=Assert-GameplayHdrValidatorExactEvidence $validatorPath $destination $entry "run-$Run/$($entry.name)"}
  return @{run=$Run;runId=$receipt.runId;stateSha256=Get-GameplayCanonicalStateSha $receipt $environment $collision $palette $character $camera $sequence $photoreal;packageSnapshotEpochSha256=$packageEvidence.snapshotEpochSha256;fatalAbsent=1;directory=$runDirectory;artifacts=$entries;receipts=Get-GameplayRunReceiptEvidence $runDirectory $runReceiptNames;hdrSidecars=$hdrEntries;temporalGhostEvidence=@($TemporalGhostEvidence)}
}
