function Get-CurrentTemporalGhostEvidence([string]$CaptureDirectory,$CharacterReceipt,$PhotorealReceipt,$SequenceReceipt,$ArtifactReceipt){$evidence=@();foreach($stem in @('third-day','third-dusk')){$captureName="$stem.png";$characterCapture=@($CharacterReceipt.captures|Where-Object name -eq $captureName);$photorealCapture=@($PhotorealReceipt.captures|Where-Object name -eq $captureName);$sequenceCapture=@($SequenceReceipt.captures|Where-Object name -eq $captureName);$artifactCapture=@($ArtifactReceipt.captures|Where-Object name -eq $captureName);if($characterCapture.Count-ne1-or$photorealCapture.Count-ne1-or$sequenceCapture.Count-ne1-or$artifactCapture.Count-ne1){throw "Temporal ghost pair capture provenance missing: $captureName"};$expected=Get-GameplayTemporalGhostExpectedSha $artifactCapture[0];$ghost=Get-GameplayTemporalGhostEvidence (Join-Path $CaptureDirectory "$stem-raw.png") (Join-Path $CaptureDirectory "$stem-diagnostic.png") (Join-Path $CaptureDirectory "$stem-raw-object-id.png") (Join-Path $CaptureDirectory "$stem-object-id.png") (Join-Path $CaptureDirectory "$stem-raw-depth.png") (Join-Path $CaptureDirectory "$stem-depth.png") 64 0 1152 720 $expected;if([int]$ghost.pass-ne1-or[int]$ghost.eligiblePixels-lt4096-or[int]$ghost.coveredPixels-ne[int]$ghost.eligiblePixels){throw "Temporal raw/effective full-frame ghost gate failed: $stem eligible=$($ghost.eligiblePixels) covered=$($ghost.coveredPixels) excluded=$($ghost.excludedPixels) tiles=$($ghost.eligibleTiles) mean=$($ghost.meanAbsoluteChannelDifference) ringMean=$($ghost.ringMeanAbsoluteChannelDifference) p99=$($ghost.p99MaximumChannelDifference) ringP99=$($ghost.ringP99MaximumChannelDifference) max=$($ghost.maximumChannelDifference) tileWorst=$($ghost.worstTileMaximumChannelDifference) stableLevels=$(($ghost.stableLevels|ConvertTo-Json -Compress)) ringLevels=$(($ghost.ringLevels|ConvertTo-Json -Compress))"};$null = Assert-GameplayTemporalGhostPairProvenance $captureName $characterCapture[0] $photorealCapture[0] $sequenceCapture[0] $ghost $artifactCapture[0];$evidence+=$ghost};return,$evidence
}
