    $mutated=Join-Path $hdrMutationRoot "$case.aevhdr";[IO.File]::Copy($productionSidecar,$mutated,$true)
    if($case-eq'trailing-byte'){$stream=[IO.File]::Open($mutated,[IO.FileMode]::Append,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.WriteByte(0xA5)}finally{$stream.Dispose()}}
